def get_gmail_service():
    if not os.path.exists(TOKEN_FILE):
        return None, "Not connected. Please connect your Gmail account first."
    try:
        creds = Credentials.from_authorized_user_file(TOKEN_FILE, GMAIL_SCOPES)
        if creds and creds.expired and creds.refresh_token:
            creds.refresh(Request())
            with open(TOKEN_FILE, 'w', encoding='utf-8') as f:
                f.write(creds.to_json())
        if not creds or not creds.valid:
            return None, "Session expired. Please reconnect your Gmail account."
        return build('gmail', 'v1', credentials=creds), None
    except Exception as e:
        return None, f"Authentication error: {str(e)}"

let _authMethod = null; // 'chrome' | 'web' | null

async function getAuthToken(interactive = false) {
  if (_authMethod === 'web')    return _getTokenViaWebFlow(interactive);
  if (_authMethod === 'chrome') return _getTokenViaChrome(interactive);
  // First call this session — probe Chrome API, fall back to Web flow if unsupported.
  try {
    const token = await _getTokenViaChrome(interactive);
    _authMethod = 'chrome';
    return token;
  } catch (e) {
    const msg = (e && e.message) || '';
    if (msg.includes('not supported') || msg.includes('Microsoft Edge') || msg.includes('getAuthToken')) {
      _authMethod = 'web';
      return _getTokenViaWebFlow(interactive);   // Edge: launchWebAuthFlow + Web OAuth client
    }
    throw e;
  }
}

async function gmailFetch(endpoint, options = {}, _retry = 0, _netRetry = 0) {
  const token = await getAuthToken(false);
  const url = endpoint.startsWith('http') ? endpoint : `${GMAIL_API}${endpoint}`;
  const timeoutMs = _pickTimeout(options, endpoint);  // 10s GET / 60s DELETE+batchModify
  const ctrl = new AbortController();
  const timeoutId = setTimeout(() => ctrl.abort(), timeoutMs);
  let resp;
  try {
    resp = await fetch(url, { ...options, signal: ctrl.signal,
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json', ...(options.headers||{}) } });
  } catch (e) {
    clearTimeout(timeoutId);
    if (!options.noRetry && _netRetry < GMAIL_FETCH_MAX_NETWORK_RETRIES) {
      await sleep(2000 * Math.pow(2, _netRetry));        // network backoff 2s, 4s
      return gmailFetch(endpoint, options, _retry, _netRetry + 1);
    }
    throw new Error(`Gmail API ${/* abort */ 'timeout'} : ${endpoint}`);
  }
  clearTimeout(timeoutId);
  if (resp.status === 401 && _retry === 0) {              // token expired → refresh + retry once
    await removeCachedToken();
    return gmailFetch(endpoint, options, 1, _netRetry);
  }
  if (resp.status === 429 && _retry < 3) {                // rate limited → backoff 2/4/8s
    await sleep(Math.pow(2, _retry + 1) * 1000);
    return gmailFetch(endpoint, options, _retry + 1, _netRetry);
  }
  if (!resp.ok) { const err = await resp.json().catch(() => ({})); throw new Error(err.error?.message || `Gmail API ${resp.status}`); }
  const text = await resp.text();
  return text && text.trim() ? JSON.parse(text) : {};
}

// Gmail cascade-deletes sub-labels when a parent label is removed. When iterating
// over children afterwards, Gmail returns 404 ("Requested entity was not found").
// These are NOT real errors.
function isGmailCascade404(err) {
  if (!err) return false;
  const msg = String(err.message || err);
  return /Requested entity was not found|HTTP\s*404|\b404\b/i.test(msg);
}

function classifyMessage_(message) {
  const from = message.getFrom().toLowerCase();
  const subject = message.getSubject().toLowerCase();
  const rokidResult = classifyRokid_(message);   // special rule runs first
  if (rokidResult) return rokidResult;
  for (const [labelName, rules] of Object.entries(TIER_RULES)) {
    if (labelName.includes("Rokid")) continue;
    for (const domain of rules.from) {
      if (from.includes(domain.toLowerCase())) return labelName;
    }
    for (const keyword of rules.subject) {
      if (subject.includes(keyword.toLowerCase())) return labelName;
    }
  }
  return null;   // → falls through to Triage
}

function classifyNewEmails() {
  const startTime = new Date();
  const MAX_RUNTIME_MS = 5 * 60 * 1000;
  const threads = GmailApp.search("in:inbox is:unread", 0, 50);
  let classified = 0, unclassified = 0;
  for (const thread of threads) {
    if (new Date() - startTime > MAX_RUNTIME_MS) break;   // GAS 6-min quota guard
    const messages = thread.getMessages();
    const labelName = classifyMessage_(messages[messages.length - 1]);
    if (labelName) {
      const label = getLabel_(labelName);
      const parentName = labelName.split("/")[0];
      if (parentName !== labelName) thread.addLabel(getLabel_(parentName));
      thread.addLabel(label);
      thread.moveToArchive();
      classified++;
    } else { unclassified++; }
  }
  Logger.log("Classified: " + classified + " | Unclassified: " + unclassified);
}

