def config_to_filters(config):
    filters = []
    for tier_name, tier_data in config['tiers'].items():
        for label_name, rules in tier_data.get('labels', {}).items():
            full_label = f"{tier_name}/{label_name}"
            # Senders: batch into groups of 5 for OR queries
            for i in range(0, len(rules.get('from', [])), 5):
                batch = rules['from'][i:i + 5]
                filters.append({'query': ' OR '.join(f'from:{d}' for d in batch),
                                'label': full_label})
            # Subjects: batch into groups of 5
            for i in range(0, len(rules.get('subject', [])), 5):
                batch = rules['subject'][i:i + 5]
                filters.append({'query': ' OR '.join(f'subject:({kw})' for kw in batch),
                                'label': full_label})
    return filters

async function aiTriageBatch(maxCount = 25) {
  const config = await getConfig();
  const tierNames = Object.keys(config.tiers || {});
  if (tierNames.length === 0)
    throw new Error('NO_TIERS_CONFIGURED: AI Triage needs at least one tier with sublabels...');
  // Build the set of labels the LLM is allowed to return
  const validTargets = new Set();
  for (const tn of tierNames) {
    validTargets.add(tn);
    for (const s of Object.keys(config.tiers[tn].labels || {})) validTargets.add(`${tn}/${s}`);
  }
