async function callGeminiAPI(userMessage, config, locale) {
  const apiKey = config.settings?.gemini_api_key;
  if (!apiKey) throw new Error('NO_API_KEY');
  const systemPrompt = buildSystemPrompt(config, locale);
  const resp = await fetch(
    `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${apiKey}`,
    { method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [{ role: 'user', parts: [{ text: systemPrompt + '\n\nUser: ' + userMessage }] }],
        generationConfig: { maxOutputTokens: 200, temperature: 0.7 } }) });
  if (!resp.ok) { const err = await resp.json().catch(() => ({})); throw new Error(err.error?.message || `Gemini API ${resp.status}`); }
  const data = await resp.json();
  return data.candidates?.[0]?.content?.parts?.[0]?.text || 'Sorry, I could not generate a response.';
}

