function sendMessage(action, data = {}) {
  return new Promise((resolve) => {
    chrome.runtime.sendMessage({ action, ...data }, (response) => {
      resolve(response);
    });
  });
}

async function resolveWildcardLabels(pattern) {
  // '2*' or 'Upd*' → ask the worker to match against the live label list
  const result = await sendMessage('resolveWildcard', { pattern });
  return result?.labels || [];
}

let _stuckState = null;  // { labels: [...], attempt: n }

async function retryStuckLabels() {
  if (!_stuckState || !_stuckState.labels?.length) return;
  const ids = _stuckState.labels.map(l => l.id).filter(Boolean);
  const attempt = _stuckState.attempt || 1;
  const result = await sendMessage('retryStuckLabels', { ids });
  const stillStuck = result?.stuck || [];
  if (stillStuck.length === 0) {
    _stuckState = null;                              // success
  } else if (attempt === 1) {
    _stuckState = { labels: stillStuck, attempt: 2 }; // escalate to attempt 2
  } else {
    guideManualCleanup();                            // give up → show manual steps
  }
}
